    copertina: { base: "/img/progetti/museo-della-bicicletta/museo-della-bicicletta-01", w: 1000, h: 667, alt: "Museo della Bicicletta nei sotterranei di Palazzo Gradari, Pesaro: sala espositiva con le gigantografie" },
